-- AUTH 自有翻译表；无跨 Schema 外键，管理用例在本地事务中验证 Message 引用。
CREATE TABLE auth_i18n_message_definition (
    id varchar(19) NOT NULL,
    namespace varchar(128) NOT NULL,
    message_key varchar(160) NOT NULL,
    description varchar(1000),
    enabled boolean NOT NULL DEFAULT true,
    version bigint NOT NULL DEFAULT 0,
    deleted boolean NOT NULL DEFAULT false,
    created_by varchar(128) NOT NULL,
    created_at timestamptz NOT NULL,
    updated_by varchar(128) NOT NULL,
    updated_at timestamptz NOT NULL,
    CONSTRAINT pk_auth_i18n_message_definition PRIMARY KEY (id),
    CONSTRAINT uk_auth_i18n_message_definition_key UNIQUE (namespace, message_key),
    CONSTRAINT ck_auth_i18n_message_definition_namespace CHECK (
        namespace = 'auth' OR namespace ~ '^auth(?:\.[a-z][a-z0-9-]*)+$'),
    CONSTRAINT ck_auth_i18n_message_definition_key CHECK (
        message_key ~ '^[a-zA-Z][a-zA-Z0-9]*(?:[._-][a-zA-Z0-9]+)*$'),
    CONSTRAINT ck_auth_i18n_message_definition_version CHECK (version >= 0)
);

CREATE INDEX ix_auth_i18n_message_definition_runtime
    ON auth_i18n_message_definition (namespace, enabled, message_key, id) WHERE NOT deleted;

CREATE TABLE auth_i18n_translation (
    id varchar(19) NOT NULL,
    message_id varchar(19) NOT NULL,
    locale_code varchar(35) NOT NULL,
    message_text varchar(4096) NOT NULL,
    version bigint NOT NULL DEFAULT 0,
    deleted boolean NOT NULL DEFAULT false,
    created_by varchar(128) NOT NULL,
    created_at timestamptz NOT NULL,
    updated_by varchar(128) NOT NULL,
    updated_at timestamptz NOT NULL,
    CONSTRAINT pk_auth_i18n_translation PRIMARY KEY (id),
    CONSTRAINT uk_auth_i18n_translation_message_locale UNIQUE (message_id, locale_code),
    CONSTRAINT ck_auth_i18n_translation_locale CHECK (
        locale_code ~ '^[a-z]{2,3}(?:-[A-Z][a-z]{3})?(?:-[A-Z]{2}|-[0-9]{3})?$'),
    CONSTRAINT ck_auth_i18n_translation_text CHECK (length(message_text) BETWEEN 1 AND 4096 AND message_text !~ E'[\\x01-\\x08\\x0B\\x0C\\x0E-\\x1F\\x7F]' AND message_text !~ '<[^>]*>'),
    CONSTRAINT ck_auth_i18n_translation_version CHECK (version >= 0)
);

CREATE INDEX ix_auth_i18n_translation_runtime
    ON auth_i18n_translation (locale_code, message_id, id) WHERE NOT deleted;

-- Auth 现有 ErrorCode 的中英文译文；后续管理 API 可版本化修改。

-- Web 仅保存稳定 Key，译文由所属 Owner 的数据库维护。占位符按 Key Contract 转为数字位置格式。
